window.DOC_TXT=window.DOC_TXT||{};DOC_TXT["d09_akt2"]={"title": "1006.3-ТО3", "pages": 79, "pagesTxt": ["[стр. 1]\n2024\r\nРАБОТЫ ПО РАЗРАБОТКЕ РАЗРЕШИТЕЛЬНОЙ И \r\nЭКСПЛУАТАЦИОННОЙ ДОКУМЕНТАЦИИ,\r\nИНСПЕКТОРСКОМУ НАДЗОРУ ЗА ТЕХНИЧЕСКИМ \r\nСОСТОЯНИЕМ, ОКАЗАНИЮ ИНЖИНИРИНГОВЫХ, \r\nАНАЛИТИЧЕСКИХ И КОНСУЛЬТАЦИОННЫХ УСЛУГ ПО \r\nОБЕСПЕЧЕНИЮ БЕЗОПАСНОСТИ И НАДЕЖНОСТИ \r\nГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЙ НОРИЛЬСКОЙ \r\nОБОГАТИТЕЛЬНОЙ ФАБРИКИ ООО «МЕДВЕЖИЙ \r\nРУЧЕЙ»\r\nТЕХНИЧЕСКИЙ ОТЧЁТ \r\nИнспекторский надзор за отчётный период I полугодия \r\n2024 г гидротехнические сооружения никелевого \r\nотстойника Норильской обогатительной фабрики\r\n1006.3-ТО 3", "[стр. 2]\n", "[стр. 3]\n", "[стр. 4]\nСОДЕРЖАНИЕ\r\nСостав отчетной документации .........................................................................5\r\nТЕРМИНЫ И ОПРЕДЕЛЕНИЯ............................................................................6\r\nВВЕДЕНИЕ. .........................................................................................................9\r\n1 Общая информация....................................................................................10\r\n1.1 Полное и сокращённое наименование объекта обследования .................. 10\r\n1.2 Адрес (местоположение) объекта ................................................................ 10\r\n1.3 Сведения о собственнике ГТС...................................................................... 10\r\n1.4 Сведения об эксплуатирующей организации .............................................. 10\r\n1.5 Сведения о разработчике проекта ............................................................... 10\r\n1.6 Сведения о Застройщике.............................................................................. 11\r\n1.7 Сроки ввода объекта в эксплуатацию.......................................................... 11\r\n1.8 Сведения об исполнителе инспекторского надзора.................................... 12\r\n1.8.1 Сроки выполнения работ по инспекторскому надзору....................... 12\r\n1.8.2 Сведения о приборном оснащении, применяемом при \r\nобследовании............................................................................................ 13\r\n2 Сведения о технической документации по объекту .................................14\r\n2.1 Перечень технической документации, использованной при \r\nобследовании ................................................................................................ 14\r\n3 Состав работ по инспекторскому надзору ................................................15\r\n3.1 Цели инспекторского надзора....................................................................... 15\r\n3.2 Состав надзорных сооружений..................................................................... 15\r\n3.3 Состав выполняемых работ.......................................................................... 15\r\n4 СВЕДЕНИЯ О ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЯХ \r\nНИКЕЛЕВОГО ОТСТОЙНИКА....................................................................16\r\n4.1 Форма собственности.................................................................................... 16\r\n4.2 Сведения о составе технологических решений по объектам \r\nобследования ................................................................................................ 16\r\n4.3 Гидротехнические сооружения никелевого отстойника НОФ ..................... 18\r\n4.3.1 ГТС никелевого отстойника отсек «Северный».................................. 19\r\n4.3.2 ГТС никелевого отстойника отсек «Южный» ...................................... 21\r\n4.3.3 ГТС никелевого отстойника отсек «Восточный» ................................ 23\r\n5 Результаты инспекторского надзора.........................................................25\r\n5.1 Результаты натурных наблюдений............................................................... 25\r\n5.1.1 Первый квартал 2024 года. Гидротехнические сооружения \r\nникелевого отстойника ............................................................................. 25\r\n5.1.2 Дефекты и несоответствия.................................................................. 33\r\n5.1.3 Второй квартал 2024 года.................................................................... 45\r\n5.1.4 Дефекты и несоответствия.................................................................. 53\r\n5.2 Изменение уровня безопасности ГТС никелевого отстойника \r\nНОФ за 2023 год. ........................................................................................... 55\r\n5.2.1 Изменение уровня безопасности ГТС никелевого \r\nотстойника НОФ отсек «Северный» за 2023 год..................................... 55", "[стр. 5]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n4\r\n5.2.2 Изменение уровня безопасности ГТС никелевого \r\nотстойника НОФ отсек «Южный» за 2023 год. ........................................ 55\r\n5.2.3 Изменение уровня безопасности ГТС никелевого \r\nотстойника НОФ отсек «Восточный» за 2023 год.................................... 55\r\n6 Основные выводы и рекомендации...........................................................56\r\nСписок литературы ...........................................................................................57\r\nПриложение А....................................................................................................59\r\nПриложение Б....................................................................................................77", "[стр. 6]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n5\r\nСОСТАВ ОТЧЕТНОЙ ДОКУМЕНТАЦИИ\r\nНомер \r\nтома\r\nОбозначение Наименование Примечание\r\n1006\r\nРаботы по разработке разрешительной и \r\nэксплуатационной документации, инспекторскому \r\nнадзору за техническим состоянием, оказанию \r\nинжиниринговых, аналитических и консультационных \r\nуслуг по обеспечению безопасности и надёжности \r\nгидротехнических сооружений Норильской \r\nОбогатительной Фабрики ООО «Медвежий ручей».\r\nТехнический отчёт\r\n1 1006.3-ТО 3\r\nИнспекторский надзор за отчётный период I \r\nполугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной \r\nфабрики", "[стр. 7]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n6\r\nТЕРМИНЫ И ОПРЕДЕЛЕНИЯ\r\nВ отчёте использованы термины и определения по ГОСТ Р 22.2.09-2015[11] , ГОСТ 27751-\r\n2014[14], СТО 70238424.27.010.011-2008 [15].\r\nТехническое состояние гидротехнических сооружений\r\nНормативное техническое состояние: Категория технического состояния, при котором \r\nколичественные и качественные значения параметров всех критериев оценки технического \r\nсостояния строительных конструкций зданий и сооружений, включая состояние грунтов \r\nоснования, соответствуют установленным в проектной документации значениям с учётом \r\nпределов их изменения.\r\nРаботоспособное техническое состояние: Категория технического состояния, при \r\nкоторой некоторые из числа оцениваемых контролируемых параметров не отвечают \r\nтребованиям проекта или норм, но имеющиеся нарушения требований в конкретных условиях \r\nэксплуатации не приводят к нарушению работоспособности, и необходимая несущая \r\nспособность конструкций и грунтов основания с учётом влияния имеющихся дефектов и \r\nповреждений обеспечивается.\r\nОграниченно-работоспособное техническое состояние: Категория технического \r\nсостояния строительной конструкции или здания и сооружения в целом, включая состояние \r\nгрунтов основания, при которой имеются крены, дефекты и повреждения, приведшие к снижению \r\nнесущей способности, но отсутствует опасность внезапного разрушения, потери устойчивости \r\nили опрокидывания, и функционирование конструкций и эксплуатация здания или сооружения \r\nвозможны либо при контроле (мониторинге) технического состояния, либо при проведении \r\nнеобходимых мероприятий по восстановлению или усилению конструкций и (или) грунтов \r\nоснования и последующем мониторинге технического состояния (при необходимости).\r\nАварийное состояние: Категория технического состояния строительной конструкции \r\nили здания и сооружения в целом, включая состояние грунтов основания, характеризующаяся \r\nповреждениями и деформациями, свидетельствующими об исчерпании несущей способности и \r\nопасности обрушения и (или) характеризующаяся кренами, которые могут вызвать потерю \r\nустойчивости объекта.\r\nЭксплуатационное состояние гидротехнических сооружений, принятое в \r\nЗФ «ГК «Норильский Никель» \r\nКлассификация технического состояния ГТС принятая в ЗФ «ГК «Норильский Никель» (по \r\nГОСТ Р 59873-2021[16] Гидроэлектростанции. Методика определения критериев безопасности \r\nдля декларируемых гидротехнических сооружений принята следующая):\r\nНадёжное (работоспособное) эксплуатационное состояние ГТС – состояние, при \r\nкотором сооружение соответствует всем требованиям нормативных документов и проекта при \r\nдействии нагрузок основного сочетания, значения контролируемых показателей состояния \r\nсооружений не превышают (не менее) соответствующих критериев безопасности 1-го уровня, \r\nсооружение можно эксплуатировать без разработки каких-либо мероприятий, повышающих \r\nбезопасность его эксплуатации.\r\nУдовлетворительное (частично работоспособное) эксплуатационное состояние \r\nГТС – со-стояние, при котором значение хотя бы одного контролируемого показателя стало \r\nбольше (меньше) соответствующих критериев безопасности 1-го уровня, но значения \r\nконтролируемых показателей состояния сооружений не превышают (не менее) соответствующих \r\nкритериев без-опасности 2-го уровня и сооружение находится под действием нагрузок и", "[стр. 8]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n7\r\nвоздействий, не превышающих предусмотренные проектом значения нагрузок особого \r\nсочетания.\r\nПри этом ГТС можно эксплуатировать при условии разработки и выполнения в \r\nопределённые сроки необходимых мероприятий. Эти мероприятия разрабатываются на основе \r\nанализа конкретных показателей по факторам, которые могут создать аварийную ситуацию, и \r\nсодержат необходимые меры по нейтрализации действия таких факторов.\r\nПредаварийное (предельное) эксплуатационное состояние ГТС \r\n(неработоспособное) – состояние, при котором сооружение имеет повреждения или дефекты, \r\nпри которых оно не может эксплуатироваться при воздействии основного сочетания нагрузок \r\nввиду угрозы аварии, и (или) сооружение находится под воздействием особого сочетания \r\nнагрузок, превышающих допускаемые проектом значения с угрозой аварии, и (или) появляются \r\nпризнаки прогрессирующего развития деструктивных процессов, необратимо ведущих к аварии.\r\nПри таком состоянии ГТС его нельзя эксплуатировать в проектном режиме.\r\nКлассификация уровня безопасности принята по ГОСТ Р 22.2.09-2015\r\nНормальный уровень безопасности - Сооружение удовлетворяет всем проектным \r\nтребованиям по назначению и конструктивной надёжности, а также современным нормативным \r\nтребованиям; эксплуатация осуществляется в соответствии с действующими законодательными \r\nактами, нормами и правилами. Дальнейшая эксплуатация сооружений и оборудования возможна \r\nбез проведения каких-либо технических или организационных мероприятий по повышению \r\nбезопасности при обеспечении мониторинга безопасности и своевременном выполнении \r\nплановых ремонтно-профилактических работ.\r\nПониженный уровень безопасности) - Имеются те или иные отклонения от правил\r\nбезопасной эксплуатации, не устранённые своевременно в ходе плановых мероприятий по \r\nобеспечению нормального уровня безопасности, которые, однако, не препятствуют возможности \r\nвыполнения сооружением заданных эксплуатационных функций. Дальнейшая безопасная \r\nэксплуатация сооружения в проектном режиме возможна при обязательном выполнении в \r\nсогласованные (установленные) органами государственного надзора сроки мероприятий по \r\nповышению уровня безопасности, конкретный перечень которых вытекает из анализа факторов, \r\nобусловливающих максимальные значения показателей опасности и уязвимости.\r\nНеудовлетворительный уровень безопасности – Имеются отклонения от проектного \r\nсостояния и нарушения правил безопасной эксплуатации, которые могут привести к \r\nвозникновению аварийной ситуации. Дальнейшая эксплуатация сооружения в проектном \r\nрежиме недопустима без проведения в установленные органами государственного надзора \r\nсроки тех или иных технических (вплоть до капитального ремонта, замены оборудования и др.) \r\nи организационных мероприятий по снижению риска аварий и восстановлению нормального \r\nуровня безопасности на основе анализа факторов, обусловливающих максимальные значения \r\nпоказателей опасности и уязвимости. К проведению такого анализа и разработке мероприятий \r\nпо повышению уровня безопасности, как правило, должны привлекаться специализированные \r\nнаучно- исследовательские и проектные организации; в случае необходимости по специальным \r\nпрограммам предусматриваются полевые исследования физико-механических характеристик \r\nгрунтовых материалов, бетонных конструкций, проводятся дополнительные расчёты \r\nобоснования прочности и устойчивости сооружений и конструкций, корректируются ПДЗ \r\nконтролируемых параметров состояния и пр.\r\nОпасный (критический) уровень безопасности – свидетельствуют об аварийной \r\nситуации, уровень безопасности ГТС оценивается как критический или опасный. В этом случае \r\nдальнейшая эксплуатация сооружения в проектном режиме по условиям риска аварии \r\nнедопустима и должна осуществляться в соответствии с требованиями Постановления \r\nПравительства РФ от 27 февраля 1999 г. №237 «Об утверждении Положения об эксплуатации", "[стр. 9]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n8\r\nгидротехнического сооружения и обеспечении безопасности гидротехнического сооружения, \r\nразрешение на строительство и эксплуатацию которого аннулировано (в том числе \r\nгидротехнического сооружения, находящегося в аварийном состоянии), гидротехнического \r\nсооружения, которое не имеет собственника или собственник которого неизвестен либо от права \r\nсобственности на которое собственник отказался». Необходимо незамедлительно \r\nинформировать органы государственного надзора и в соответствии с полученным \r\nпредписанием, ввести ограничения на режим эксплуатации (снижение уровня верхнего бьефа и \r\nдр.), разработать и утвердить временные правила эксплуатации. Мероприятия по \r\nвосстановлению нормального уровня безопасности должны выполняться на основании анализа \r\nфакторов, обусловливающих возникновение аварийной ситуации, с обязательным \r\nпривлечением специализированных организаций. После проведения необходимых мероприятий \r\nперевод сооружений вновь в проектный режим эксплуатации должен быть согласован с \r\nорганами государственного надзора за безопасностью ГТС.\r\nКатегория опасности дефектов\r\nПри оценке опасности дефектов в настоящем отчёте принята классифицированы по \r\nСТО 70238424.27.010.011-2008, в котором применены термины и понятия, установленные \r\nФедеральным законом от 21.07.1997 № ФЗ-117 «О безопасности гидротехнических \r\nсооружений»:\r\n«А» - Дефекты и повреждения основных несущих конструкций, представляющие \r\nнепосредственную опасность их разрушения.\r\n«Б» - Дефекты и повреждения, не представляющие при их обнаружении \r\nнепосредственную опасность разрушения несущих конструкций, но способные в дальнейшем \r\nвызвать повреждения других элементов и узлов или при развитии повреждения перейти в \r\nкатегорию «А».\r\n«В» - Дефекты и повреждения локального характера, которые при последующем развитии \r\nне могут оказать влияния на основные несущие конструкции", "[стр. 10]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n9\r\nВВЕДЕНИЕ.\r\nРаботы по разработке разрешительной и эксплуатационной документации, \r\nинспекторскому надзору за техническим состоянием и оказанию инжиниринговых, \r\nаналитических и консультационных услуг по обеспечению безопасности и надёжности\r\nгидротехнических сооружений Норильской обогатительной фабрики ООО «Медвежий ручей» \r\nвыполнены специалистами ООО «Институт Красноярскгидропроект» на основании договора № \r\nМР 2450/2023 от 22.08.2023 г. между Обществом с ограниченной ответственностью «Медвежий \r\nручей» (ООО «Медвежий ручей» и Обществом с ограниченной ответственностью «Проектно￾изыскательский институт Красноярскгидропроект» (ООО «Институт Красноярскгидропроект»).\r\nИнспекторский надзор выполнен в соответствии с техническим заданием, техническое \r\nзадание на выполнение работ приведено в Приложении А.\r\nВ пункте 3 технического задания подпунктом 3.3 включены Отстойник никелевого \r\nконцентрата «Северный», «Южный», «Восточный» НОФ. В пункте 5 подпунктами 5.3, 5.8, 5.9 \r\nпредусмотрено выполнение следующих документов: \r\n- Разработка правил эксплуатации ГТС отстойников никелевого концентрата НОФ;\r\n- Разработка проекта эксплуатации ГТС никелевых отстойников НОФ;\r\n- Оказание услуг по инспекторскому надзору, инжиниринговых, аналитических и \r\nконсультационных услуг.\r\nЦель инспекторского надзора инжиниринговых, аналитических и консультационных услуг \r\nпо обеспечению безопасности и надежности ГТС НОФ является обеспечение контроля, надзора \r\nсоответствия ГТС НОФ установленным нормам и требованиям нормативно-правовых актов РФ, \r\nтребованиям проектной документации, повышение уровня безопасности ГТС НОФ. \r\nВ отчёте по инспекторскому надзору отражено фактическое состояние гидротехнических \r\nсооружений никелевого отстойника (отсеки «Северный», «Южный», «Восточный») Норильской \r\nобогатительной фабрики, приведены фотоматериалы дефектов, даны рекомендации по \r\nразработке мероприятий повышения надёжности и безопасности ГТС Никелевого отстойника \r\nНОФ.", "[стр. 11]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n10\r\n1 ОБЩАЯ ИНФОРМАЦИЯ\r\n1.1 Полное и сокращённое наименование объекта обследования\r\nПолное наименование: Гидротехнические сооружения никелевого отстойника (отсеки \r\n«Северный», «Южный», «Восточный») Норильской обогатительной фабрики.\r\nСокращённое наименование: ГТС Никелевого отстойника НОФ.\r\n1.2 Адрес (местоположение) объекта\r\nРоссийская Федерация, Красноярский край, Норильский промышленный район, \r\nг. Норильск. Енисейский бассейновый округ.\r\nПлощадка ГТС Никелевого отстойника НОФ расположена в акватории бывшего озера \r\nШкольное и в ложе двух небольших безымянных озер.\r\n1.3 Сведения о собственнике ГТС\r\nПолное наименование: Общество с ограниченной ответственностью «Медвежий ручей».\r\nСокращённое наименование: ООО «Медвежий ручей».\r\nМесто нахождения: Российская Федерация, Красноярский край, г. Норильск.\r\nПочтовый адрес: 663316 Российская Федерация, Красноярский край, г. Норильск, \r\nул. Горная, д.13\r\nТел./факс: (3919) 26-11-51/26-39-36.\r\nE-mail: PriemnayaMR@nornik.ru.\r\n1.4 Сведения об эксплуатирующей организации\r\nПолное наименование: Общество с ограниченной ответственностью «Медвежий ручей».\r\nСокращённое наименование: ООО «Медвежий ручей».\r\nМесто нахождения: Российская Федерация, Красноярский край, г. Норильск.\r\nПочтовый адрес: 663316, Российская Федерация, Красноярский край, г. Норильск, \r\nул. Горная, д.13\r\nТел./факс: (3919) 26-11-51/26-39-36\r\nE-mail: PriemnayaMR@nornik.ru.\r\nГенеральный директор Зайцев Владимир Игнатьевич, действующий на основании устава.\r\nЭксплуатация ГТС Никелевого отстойника осуществляется работниками ЦГТС и ГТ (цех \r\nгидротехнических сооружений и гидротранспорта), ООО «Медвежий ручей».\r\n1.5 Сведения о разработчике проекта\r\nРазработку проектов на сооружения отстойников никелевого концентрата выполнял \r\nизначально проектный отдел Норильского комбината, в дальнейшем институт \r\n«Норильскпроект», который был создан на базе проектной конторы Норильского комбината. На", "[стр. 12]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n11\r\nданный момент институт «Норильскпроект» является филиалом Общества с ограниченной \r\nответственностью «Институт Гипроникель», в связи с реорганизацией профильные отделы, \r\nзанимающиеся гидротехническими сооружениями, были упразднены. \r\nПолное наименование: Общество с ограниченной ответственностью «Институт \r\nГипроникель».\r\nСокращённое наименование: ООО «Институт Гипроникель».\r\nЮридический адрес: 195220, город Санкт-Петербург, проспект Гражданский, дом 11. \r\nТелефон:8-812-335-31-24.\r\nФакс: 8-812-335-32-72.\r\nЭлектронный адрес: gn@nornik.ru.\r\nВ настоящее время, разработкой проектов эксплуатации и инженерным сопровождением \r\nв целом занимается Акционерное общество «Механобр инжиниринг».\r\nПолное наименование: Акционерное общество «Механобр инжиниринг».\r\nСокращённое наименование: АО «Механобр инжиниринг».\r\nЮридический адрес: 199106, город Санкт-Петербург, линия 22-я В.О., дом 3 корпус 7 \r\nлитер к, офис 204. \r\nТелефон:8-812-324-89-24.\r\nФакс: 8-812-321-37-70.\r\nЭлектронный адрес: office@mekhanobr.com.\r\n1.6 Сведения о Застройщике\r\nСтроительной организацией являлось СУ «Никельстрой». Правопреемник данной \r\nорганизации – ООО «Заполярная строительная компания» (г. Норильск).\r\nПолное наименование: Общество с ограниченной ответственностью «Заполярная \r\nстроительная компания».\r\nСокращённое наименование: ООО «ЗСК».\r\nЮридический адрес: 663316, Красноярский край, г. Норильск, ул. Октябрьская, д.14.\r\nИНН: 2457061775.\r\nОГРН: 1062457022880.\r\nТелефон: 8 (3919) 45-01-00\r\nФакс: 8 (3919) 45-24-63\r\nЭлектронный адрес: zsk@nornik.ru\r\n1.7 Сроки ввода объекта в эксплуатацию\r\nГТС Никелевого отстойника НОФ введены в эксплуатацию в 1974 г (акт рабочей комиссии \r\n№ 250 от 31.03.1974 г). Фактический срок эксплуатации – 50 лет.\r\nНа основании проектной документации срок эксплуатации ГТС Никелевого отстойника\r\nНОФ – не определен, так как все отсеки никелевого отстойника являются буферными и \r\nобеспечивают необходимый объем складирования с учетом своевременных перекачек", "[стр. 13]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n12\r\nметаллосодержащего продукта земснарядами и возврата осветленной воды из отсеков в \r\nтехнологический цикл НОФ.\r\nНормативный срок эксплуатации для сооружений IV класса – 50 лет, согласно \r\nСП 58.13330.2019 «Гидротехнические сооружения. Основные положения».\r\n1.8 Сведения об исполнителе инспекторского надзора\r\nПолное наименование организации: Общество с ограниченной ответственностью \r\n«Проектно-изыскательский институт Красноярскгидропроект».\r\nСокращённое наименование организации: ООО «Институт Красноярскгидропроект».\r\nМестонахождение организации: (индекс, регион, город) РФ, Красноярский край, \r\n660075, г. Красноярск, ул. Маерчака,8, стр. №2, пом.9, оф.227.\r\nФактический адрес организации: РФ, Красноярский край, 660075, г. Красноярск, ул. \r\nМаерчака,8, стр. №2, пом.9, оф.227.\r\nРуководитель организации: Генеральный директор ООО «Институт \r\nКрасноярскгидропроект», действующий на основании Устава, Вайкум Владимир Андреевич\r\nТелефон * (391)204 12 84; (923)2887993, (983)2054188.\r\nЭлектронная почта kgp24@yandex.ru\r\n1.8.1 Сроки выполнения работ по инспекторскому надзору\r\nИнспекторский надзор по обследованию ГТС Никелевого отстойника НОФ выполнялся в \r\nнесколько этапов, сроки выполнения работ по инспекторскому надзору приведены Таблица 1.1.\r\nТаблица 1.1 – Сроки проведения обследования\r\n№ \r\nп/п\r\nПеречень выполняемых работ Начало работ Окончание работ\r\n1 Проведение визуального и \r\nинструментального обследования ГТС 26.02.2024 04.02.2024\r\n2 Проведение визуального и \r\nинструментального обследования ГТС 24.06.2024 27.06.2024\r\nОбработка полевых материалов, анализ, \r\nсоставление отчёта 1.01.2024 27.06.2024", "[стр. 14]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n13\r\n1.8.2 Сведения о приборном оснащении, применяемом при обследовании\r\nПри выполнении работ по инспекторскому надзору были использованы следующие \r\nинженерные и измерительные приборы, техническое и компьютерное оборудование:\r\n– Экшн-камера GoPro MAX 360;\r\n– Смартфон;\r\n– Рулетка мерная 5 м.", "[стр. 15]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n14\r\n2 СВЕДЕНИЯ О ТЕХНИЧЕСКОЙ ДОКУМЕНТАЦИИ ПО ОБЪЕКТУ\r\n2.1 Перечень технической документации, использованной при \r\nобследовании\r\n– Декларация безопасности гидротехнических сооружений никелевого отстойника \r\n(отсеки «Северный, «Южный», «Восточный») Норильской обогатительной фабрики, \r\nООО «Медвежий ручей» совместно со специалистами ООО «Мигруп Проект», \r\nНорильск, 01.09.2023 г.\r\n– Правила эксплуатации гидротехнических сооружений никелевого отстойника \r\n(отсеки «Северный», «Южный», «Восточный») Норильской обогатительной \r\nфабрики. Шифр 1006.3-ПЭ. ООО «Институт Красноярскгидропроект», 2023 г.\r\n– Проект эксплуатации гидротехнических сооружений никелевого отстойника (отсеки \r\n«Северный», «Южный», «Восточный») Норильской обогатительной фабрики на \r\n2024÷2025 гг. Шифр 1006.3-ПрЭ. ООО «Институт Красноярскгидропроект», 2023 г.\r\n– Проект мониторинга безопасности гидротехнических сооружений никелевого \r\nотстойника (отсеки «Северный», «Южный», «Восточный») Норильской \r\nобогатительной фабрики Шифр 07-04-231. ООО «Мигруп Проект», 2023 г.\r\n– План ликвидации (локализации) аварий в цехе гидротехнических сооружений и \r\nгидротранспорта Норильской обогатительной фабрики (никелевые отстойники) \r\n2023 г. ООО «Медвежий ручей», 15.12.2022 г.", "[стр. 16]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n15\r\n3 СОСТАВ РАБОТ ПО ИНСПЕКТОРСКОМУ НАДЗОРУ\r\n3.1 Цели инспекторского надзора\r\nИнспекторский надзор за техническим состоянием гидротехнических сооружений \r\nникелевого отстойника Норильской обогатительной фабрики выполняется с целью оценки \r\nфактического состояния грунтовых сооружений, механического оборудования и трубопроводов, \r\nдинамики развития процессов и получения исходных данных для разработки рекомендаций и \r\nпроведения ремонтных работ службой эксплуатации ГТС.\r\n3.2 Состав надзорных сооружений\r\nОсновные гидротехнические сооружения никелевого отстойника (отсеки «Северный», \r\n«Южный», «Восточный») Норильской обогатительной фабрики:\r\n– Ограждающая дамба «Северного», «Южного» и «Восточного» отсеков Никелевого \r\nотстойника. Отсеки служат для приема технологических стоков из НОФ и УСНК;\r\n– Сифонный водозабор. Водозабор служит для забора осветленной воды из \r\nСеверного отстойника во всасывающий коллектор береговой насосной станции никелевого\r\nконцентрата;\r\n– Береговая насосная станция никелевого концентрата. Насосная станция служит \r\nдля возврата из емкости отсеков осветленной оборотной воды в технологический цикл НОФ, а \r\nтакже для подачи металлосодержащего продукта на УСНК;\r\n– Система трубопроводов (подводящих и отводящих);\r\nТакже в эксплуатации находится плавучая насосная станция (ПлНС). Для перекачки \r\nметаллосодержащего продукта используется технологическое оборудование – земснаряды.\r\n3.3 Состав выполняемых работ\r\nРаботы по обследованию подразделяются на полевые и камеральные.\r\nПолевые работы\r\nК полевым относятся работы по техническому обследованию сооружений:\r\n– визуальный осмотр сооружений;\r\n– осмотр КИА;\r\n– установка КИА (установка температурных датчиков на низовом откосе;\r\n– выявление изменений в сооружениях, влияющих на работу ГТС;\r\n– фотофиксация дефектов.\r\nКамеральные работы\r\nВ камеральные работы входит:\r\nанализ полученных данных в ходе визуального осмотра сооружений; составление отчёта \r\nс рекомендациями", "[стр. 17]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n16\r\n4 СВЕДЕНИЯ О ГИДРОТЕХНИЧЕСКИХ СООРУЖЕНИЯХ \r\nНИКЕЛЕВОГО ОТСТОЙНИКА \r\n4.1 Форма собственности\r\nЧастная.\r\n4.2 Сведения о составе технологических решений по объектам\r\nобследования\r\nОбследование гидротехнических сооружений никелевого отстойника (отсеки «Северный, \r\n«Южный», «Восточный») Норильской обогатительной фабрики, проводилось специалистами –\r\nгидротехниками путём пешего обхода напорного фронта никелевого отстойника зимой и летом\r\n2024 года Обход проводился по всей длине напорного фронта по нижнему бьефу и по верхнему \r\nбьефу с фотофиксацией выявленных отклонений и несоответствий. Каждый фотоснимок \r\nнумеровался. Затем по координатам, вшитым в свойства фотоснимков точки стояния внесены \r\nна карту планеты в программе Google Earth Pro.\r\nПосле нанесения точек стояния на схему с пикетами каждая фотография была \r\nпроанализирована согласно требованиям технического задания. После проведённого анализа \r\nсделаны выводы и даны рекомендации по повышению уровня безопасности ГТС никелевого \r\nотстойника НОФ.", "[стр. 18]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n17\r\nРисунок 4.1 – Схема гидротехнических сооружений никелевого отстойника (отсеки \r\n«Северный», «Южный», «Восточный») Норильской обогатительной фабрики", "[стр. 19]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n18\r\nРисунок 4.2 Схема гидротехнических сооружений никелевого отстойника (отсеки \r\n«Северный», «Южный», «Восточный») Норильской обогатительной фабрики с \r\nпикетажем и места фотофиксации\r\n4.3 Гидротехнические сооружения никелевого отстойника НОФ\r\nОбследование объектов ГТС проводилось в конце февраля начале марта 2024. \r\nТемпература воздуха в течение суток колебалась в пределах -20 - - -40°С. Особое внимание \r\nбыло уделено сооружениям. Ниже приведены фотографии сооружений. \r\nВторое обследование объектов ГТС проводилось в конце июня 2024. Особое внимание \r\nбыло уделено сооружениям. Ниже приведены фотографии сооружений. \r\nВ процессе обследования были зафиксированы ряд дефектов и несоответствий, которые \r\nмогут привести к снижению уровня безопасности ГТС в случае их развития т непринятия мер. \r\nДанная информация отражена на фотоснимках и автоматически зафиксирована в свойствах \r\nфотоснимка – время съемки и координаты места.", "[стр. 20]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n19\r\n4.3.1 ГТС никелевого отстойника отсек «Северный»\r\nРисунок 4.3 График изменения уровня воды в отсеке «Северный» никелевого \r\nотстойника в январе 2024 г\r\nРисунок 4.4 График изменения уровня воды в отсеке «Северный» никелевого \r\nотстойника в феврале 2024 г\r\n5,00\r\n5,05\r\n5,10\r\n5,15\r\n5,20\r\n5,25\r\n5,30\r\n5,35\r\nГрафик изменения уровня воды в отсеке \r\n\"Северный\" никелевого отстойника в январе 2024 г\r\nРяд1 Ряд2\r\n5,00\r\n5,05\r\n5,10\r\n5,15\r\n5,20\r\n5,25\r\nГрфик изменения уровня воды в \"Северном\" \r\nотсеке никелевого отстойника в феврале 2024 \r\nг\r\nСеверный Среднее", "[стр. 21]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n20\r\nРисунок 4.5 График изменения уровня воды в отсеке «Северный» никелевого \r\nотстойника в марте 2024 г\r\nРисунок 4.6 График изменения уровня воды в отсеке «Северный» никелевого \r\nотстойника в апреле 2024 г\r\nАнализируя изменение уровня воды в отсеке «Северный» в первом триместре 2024 года \r\nустановлено: \r\n– среднемесячное значение отметки уровня воды в январе 5,18 м; \r\n– среднемесячное значение отметки уровня воды в феврале 5,17 м;\r\n– среднемесячное значение отметки уровня воды в марте 5,16 м;\r\n– среднемесячное значение отметки уровня воды в апреле 5,17 м;\r\n– максимальное значение отметки уровня воды в первом триместре 5,24 м;\r\n5,00\r\n5,05\r\n5,10\r\n5,15\r\n5,20\r\n5,25\r\n5,30\r\nГрафик изменения уровня воды в отсеке \r\n\"Северный\" никелевого отстойника в марте \r\n2024 г \r\nСеверный Среднее\r\n4,90\r\n4,95\r\n5,00\r\n5,05\r\n5,10\r\n5,15\r\n5,20\r\n5,25\r\nГрафик изменения уровня воды в отсеке \r\n\"Северный\" никелевого оттойника в апреле \r\n2024 г\r\nСеверный Среднее", "[стр. 22]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n21\r\n– минимальное значение отметки уровня воды в первом триместре 5,01 м.\r\n4.3.2 ГТС никелевого отстойника отсек «Южный»\r\nРисунок 4.7 График изменения уровня воды в отсеке «Южный» никелевого \r\nотстойника в январе 2024 г\r\nРисунок 4.8 График изменения уровня воды в отсеке «Южный» никелевого \r\nотстойника в феврале 2024 г\r\n0,00\r\n20,00\r\n40,00\r\n60,00\r\n80,00\r\n100,00\r\n120,00\r\nГрафик изменения уровня воды в отсеке \r\n\"Южный\" никелевого отстойника в феврале \r\n2024 г", "[стр. 23]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n22\r\nРисунок 4.9 График изменения уровня воды в отсеке «Южный» никелевого \r\nотстойника в марте 2024 г\r\nРисунок 4.10 График изменения уровня воды в отсеке «Южный» никелевого \r\nотстойника в апреле 2024 г.\r\nАнализируя графики учтановлено что отметка уровня воды в отсее «Южном» в первом \r\nтриместре составила 118,56 м и постоянно удерживалась на одном месте. \r\n0,00\r\n20,00\r\n40,00\r\n60,00\r\n80,00\r\n100,00\r\n120,00\r\nГрафик изменения уровня воды в отсеке \r\n\"Южный\" никелевого отстйника в марте 2024 \r\nг \r\n0,00\r\n20,00\r\n40,00\r\n60,00\r\n80,00\r\n100,00\r\n120,00\r\nГрафик изменения уровня воды в отсеке \r\n\"Южный\" никелевого отстойника в апреле \r\n2024 г", "[стр. 24]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n23\r\n4.3.3 ГТС никелевого отстойника отсек «Восточный»\r\nРисунок 4.11 График изменеия уровня воды в отсеке «Восточный» никелевого \r\nотстойника в январе 2024 г\r\nРисунок 4.12 График изменеия уровня воды в отсеке «Восточный» никелевого \r\nотстойника в феврале 2024 г\r\n0,00\r\n20,00\r\n40,00\r\n60,00\r\n80,00\r\n100,00\r\n120,00\r\nГрафик изменения уровня воды в отсеке \r\n\"Восточный\" никелевого отстойника в январе \r\n2024 г\r\n0,00\r\n20,00\r\n40,00\r\n60,00\r\n80,00\r\n100,00\r\n120,00\r\nГрафик изменения уровня воды в отсеке \r\n\"Восточный\" никелевого отстойника в \r\nфеврале 2024 г", "[стр. 25]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n24\r\nРисунок 4.13 График изменеия уровня воды в отсеке «Восточный» никелевого \r\nотстойника в марте 2024 г\r\nРисунок 4.14 График изменеия уровня воды в отсеке «Восточный» никелевого \r\nотстойника в апреле 2024 г\r\nАнализируя изменения уровня воду в отсеке «Восточный» отмечаем, что отметка \r\nуровня воды в отсеке «Восточный» с 1 января по 12 апреля 2024 г была постоянной в размере \r\n109,38 м до 12.04.24. а с 13.04.24 отметка поднялась до 109,39 м. \r\n0,00\r\n20,00\r\n40,00\r\n60,00\r\n80,00\r\n100,00\r\n120,00\r\nГрафик изменения уровня воды в отсеке \r\n\"Восточный\" никелевого отстойника в марте \r\n2024 г\r\n109,37\r\n109,38\r\n109,38\r\n109,38\r\n109,38\r\n109,38\r\n109,39\r\n109,39\r\n109,39\r\n109,39\r\nГрафик изменения уровня воды в отсеке \r\n\"Восточный\" никелевого отстойника в апреле \r\n2024 г\r\nвосточный Среднее", "[стр. 26]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n25\r\n5 РЕЗУЛЬТАТЫ ИНСПЕКТОРСКОГО НАДЗОРА\r\n5.1 Результаты натурных наблюдений\r\n5.1.1 Первый квартал 2024 года. Гидротехнические сооружения никелевого \r\nотстойника\r\nРисунок 5.1 Ограждающая дамба никелевого отстойника отсек «Северный» \r\nводомерная рейка в прудке ПКᶜ3+12", "[стр. 27]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n26\r\nРисунок 5.2 Гребень разделительной дамбы отсека «Северный» и «Южный» с \r\nпульпопроводами ПКᶜ1+67\r\nРисунок 5.3 Вид на технологические трубопроводы отсека «Северный» ПКᶜ3+30", "[стр. 28]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n27\r\nРисунок 5.4 Низовой откос ограждающей дамбы отсека «Северный» ПКᶜ3+70\r\nРисунок 5.5 Вид на емкость отсека «Северный» ПКᶜ3+70", "[стр. 29]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n28\r\nРисунок 5.6 Вид на емкость отсека «Северный» ПКᶜ5+40\r\nРисунок 5.7 Вид на емкость отсека «Южный» ПК ю 0+50", "[стр. 30]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n29\r\nРисунок 5.8 Вид на емкость отсека «Южный» ПК ю1+00\r\nРисунок 5.9 Общий вид на гребень разделительной дамбы между отсеками \r\n«Северный» и «Южный» ПК ю5+00", "[стр. 31]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n30\r\nРисунок 5.10 Общий вид на гребень ограждающей дамбы отсека «Южный» ПК ю4+80\r\nРисунок 5.11 Общий вид на емкость отсека «Южный» никелевого оттойника ПК ю4+00", "[стр. 32]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n31\r\nРисунок 5.12 Общий вид на гребень ограждающей дамбы отстойника «Южный» ПК\r\nю3+30\r\nРисунок 5.13 Водоперепускное устройство между отсеками «Восточный» и\r\nСеверный» ПКᴯ0+24", "[стр. 33]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n32\r\nРисунок 5.14 Вид на гребень разделительной дамбы между отсеками «Восточный и \r\n«Северный» ПКᴯ0+50\r\nРисунок 5.15 Вид на емкость отсека «Восточный» ПКᴯ1+40", "[стр. 34]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n33\r\nРисунок 5.16 Вид на гребень ограждающей дамбы отсека «Восточный» и на \r\nводоперепускное устройство №5 ПКᴯ1+54\r\n5.1.2 Дефекты и несоответствия \r\nНа водомерной рейке, установленной на сифонном водозаборе отсутствует шкала. \r\nотображающая уровень воды в отсеке, также на рейке не обозначены критические уровни воды\r\nв отсеке ПК3+12,5. По журналу наблюдений за уровнями воды в отсеках, невозможно\r\nопределить отметку УВ в емкости северного отсека (в м БС). (Рисунок 5.17), \r\nРепер (Р-3) отсутствует ПК1+67. Все реперы из списка КИА не были найдены на \r\nместности отсутствуют (Рисунок 5.18),\r\nВ емкости южного отсека отсутствует водомерная рейка ПК2+29, при этом в журнале \r\nнаблюдений за уровнями воды в отсеках УВ в южном отсеке фиксируется регулярно (Рисунок \r\n5.19);\r\nНарушение теплоизоляции технологических трубопроводов ПК3+32 (Рисунок 5.20);\r\nКрутой низовой откос ограждающей дамбы северного отсека ПК3+59 (Рисунок 5.21),\r\nВыходы фильтрации на низовом откосе ограждающей дамбы северного отсека ПК4+50 \r\nСледы сброса воды в ручей Медвежий из здания, расположенного за низовым откосом \r\nограждающей дамбы северного отсека (здание не относится к ГТС никелевого отстойника)\r\n(Рисунок 5.22), \r\nРепер (Р-1) отсутствует ПК4+60,5 (Рисунок 5.23);\r\nРазмыв откоса разделительной дамбы между северным и южным отсеками, со стороны \r\nюжного отсека ПК0+24 (Рисунок 5.24);\r\nРазмыв откоса разделительной дамбы между северным и южным отсеками, со стороны \r\nюжного отсека ПК0+49 (Рисунок 5.25);", "[стр. 35]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n34\r\nНа водомерной рейке, установленной на водопропускном устройстве №2 не указаны \r\nкритические уровни воды ПК0+24 (Рисунок 5.26);\r\nРепер (Р-2) отсутствует ПК0+39,5 (Рисунок 5.27);\r\nНарушение теплоизоляции технологических трубопроводов на разделительной дамбе \r\nмежду северным и южным отсеками ПК1+38 (Рисунок 5.28);\r\nВыходы фильтрационных вод на низовом откосе ограждающей дамбы северного отсека \r\nПК3+02 (Рисунок 5.29); \r\nНарушение теплоизоляции и локальное обледенение технологических трубопроводов \r\nПК2+90 (Рисунок 5.30);\r\nРазмыв откоса разделительной дамбы между северным и южным отсеками, со стороны \r\nюжного отсека ПК0+00 (Рисунок 5.31);\r\nВыход фильтрационных вод на низовом откосе ограждающей дамбы южного отсека, со \r\nстороны ручья Медвежий ПК0+27 (Рисунок 5.32);\r\nПризнаки фильтрации. Наличие наледей на низовом откосе ограждающей дамбы южного \r\nотсека ПК2+50 (Рисунок 5.33);\r\nПризнаки фильтрации. Наличие наледей на низовом откосе ограждающей дамбы южного \r\nотсека ПК2+68 (Рисунок 5.34);\r\nЗахламлен верховой откос ограждающей дамбы восточного отсека, возле майны \r\nводоперепускного устройства №2 ПК0+16 (Рисунок 5.35);\r\nЗначительный перепад между отметками гребня ограждающей дамбы восточного отсека \r\n0,5 м ПК1+54 (Рисунок 5.36)\r\nРисунок 5.17 На водомерной рейке, установленной на сифонном водозаборе \r\nотсутствует шкала. отображающая уровень воды в отсеке, также на рейке не\r\nобозначены критические уровни воды в отсеке ПК3+12,5", "[стр. 36]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n35\r\nРисунок 5.18 Репер (Р-3) отсутствует ПК1+67\r\nРисунок 5.19 В емкости южного отсека отсутствует водомерная рейка ПК2+29, При \r\nэтом в журнале наблюдений за уровнями воды в отсеках УВ в южном отсеке\r\nфиксируется регулярно", "[стр. 37]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n36\r\nРисунок 5.20 Нарушение теплоизоляции технологических трубопроводов ПК3+32\r\nРисунок 5.21 Крутой низовой откос ограждающей дамбы северного отсека ПК3+59", "[стр. 38]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n37\r\nРисунок 5.22 Выходы фильтрации на низовом откосе ограждающей дамбы северного \r\nотсека ПК4+50, Следы сброса воды в ручей Медвежий из здания расположенного за \r\nнизовым откосом ограждающей дамбы северного отсека (здание не относится к ГТС \r\nникелевого отстойника)\r\nРисунок 5.23 Репер (Р-1) отсутсвует ПК4+60,5", "[стр. 39]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n38\r\nРисунок 5.24 Размыв откоса разделительной дамбы между северным и южным \r\nотсеками, со стороны южного отсека ПК0+24\r\nРисунок 5.25 Размыв откоса разделительной дамбы между северным и южным\r\nотсеками, со стороны южного отсека ПК0+49", "[стр. 40]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n39\r\nРисунок 5.26 На водомерной рейке установленной на водоперепускном устройстве \r\n№2 не указаны критические уровни воды ПК0+24\r\nРисунок 5.27 Репер (Р-2) отсутствует ПК0+39,5", "[стр. 41]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n40\r\nРисунок 5.28 Нарушение теплоизоляции технологических трубопроводов на \r\nразделительной дамбе между северным и южным отсеками ПК1+38\r\nРисунок 5.29 Выходы фильтрационных вод на низовом откосе ограждающей дамбы \r\nсеверного отсека ПК3+02", "[стр. 42]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n41\r\nРисунок 5.30 Нарушение теплоизоляции и локальное обледенение технологических \r\nтрубопроводов РК2+90\r\nРекомендации:\r\n1. Отремонтировать водомерную рейку на сифонном водозаборе; \r\n2. Восстановить репер; \r\n3. Восстановить теплоизоляцию трубопровода;\r\n4. Сделать откос более пологим;\r\n5. Отсыпать наслонный дренаж;\r\n6. Засыпать промоины на откосе.\r\n7. Очистить верховой откос вблизи майны, для предотвращения засорения \r\nводоперепускного устройства;\r\n8. Засыпать перепад грунтом с послойным уплотнением.", "[стр. 43]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n42\r\nРисунок 5.31 Размыв откоса разделительной дамбы между северным и южным \r\nотсеками, со стороны южного отсека ПК0+00\r\nРисунок 5.32 Выход фильтрационных вод на низовом откосе ограждающей дамбы \r\nюжного отсека, со стороны ручья Медвежий ПК0+27", "[стр. 44]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n43\r\nРисунок 5.33 Признаки фильтрации. Наличие наледей на низовом откосе \r\nограждающей дамбы южного остека ПК2+50\r\n \r\nРисунок 5.34 Признаки фильтрации. Наличие наледей на низовом откосе ограждающей \r\nдамбы южного остека ПК2+68", "[стр. 45]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n44\r\nРисунок 5.35 Захламлен верховой откос ограждающей дамбы восточного отсека, \r\nвозле майны водоперепускного устройства №2\r\nРисунок 5.36 Значительный перепад между отметками гребня ограждающей дамбы \r\nвосточного отсека 0,5м ПК1+54", "[стр. 46]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n45\r\n5.1.3 Второй квартал 2024 года. \r\nРисунок 5.37 Общий вид ГТС никелевого отстйника\r\nРисунок 5.38 Вид на гребень ограждающей дамбы северного отсека. ПКᶜ 3+32", "[стр. 47]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n46\r\nРисунок 5.39 Вид на гребень ограждающей дамбы северного отсека. ПКᶜ 3+50\r\nРисунок 5.40 Вид на верховой откос ограждающей дамбы северного отсека. ПКᶜ 3+59", "[стр. 48]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n47\r\nРисунок 5.41 Вид гребень ограждающей дамбы северного отсека. ПКᶜ 5+00\r\nРисунок 5.42 Вид на разделительную дамбу между северным и восточным отсеками. \r\nПКᶜ 0+00 / ПКᴯ 0+00", "[стр. 49]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n48\r\nРисунок 5.43 Вид на водоперепускное устройство №2 Уровень воды в восточном \r\nотсеке ПКᶜ 0+24 / ПКᴯ 0+24\r\nРисунок 5.44 Вид на водоперепускное устройство №1 ПКᶜ 0+54 / ПКᴯ 0+54", "[стр. 50]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n49\r\nРисунок 5.45 Вид на гребень разделительной дамбы между северным и восточным \r\nотсеками ПКᶜ 0+80 / ПКᴯ 0+80\r\nРисунок 5.46 Вид на емкость восточного отсека. Сливы никелевого концентрата. ПКᴯ\r\n1+20", "[стр. 51]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n50\r\nРисунок 5.47 Вид на водоперепускное устройство №5. ПКᴯ 1+50\r\nРисунок 5.48 Вид на гребень разделительной дамбы между северным и южным \r\nотсеками. ПКᶜ 1+20 / ПКю 5+20", "[стр. 52]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n51\r\nРисунок 5.49 – Вид на гребень ограждающей дамбы южного отсека ПКю 4+00\r\nРисунок 5.50 Вид на верховой откос ограждающей дамбы южного отека. ПК ю 4+00", "[стр. 53]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n52\r\nРисунок 5.51 Вид на низовой откос ограждающей дамбы южного отека. ПК ю 4+00", "[стр. 54]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n53\r\n5.1.4 Дефекты и несоответствия \r\nРисунок ᶜ5.52 Нарушение сплошности теплоизоляции технологических \r\nтрубопроводов. ПКᶜ 3+32\r\nРисунок 5.53 Вид на водомерную рейку в емкости северного отсека. На водомерной \r\nрейке, установленной на сифонном водозаборе отсутствует шкала отображающая\r\nуровень воды в емкости, также на рейке не обозначены критические УВ. ПКᶜ 3+12,5", "[стр. 55]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n54\r\nРисунок 5.54 – Вид на низовой откос ограждающей дамбы северного отсека. Крутой \r\nнизовой откос. ПКᶜ3+59 Крутой низовой откос\r\nРисунок 5.55 Вид на низовой откос ограждающей дамбы северного отсека. ПКᶜ 4+20\r\nЗахламление территории.", "[стр. 56]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n55\r\n5.2 Изменение уровня безопасности ГТС никелевого отстойника НОФ \r\nза 2023 год. \r\n5.2.1 Изменение уровня безопасности ГТС никелевого отстойника НОФ \r\nотсек «Северный» за 2023 год.\r\n В результате сравнения инспекторских отчетов за второе полугодие 2023 года с \r\nинспекторским отчетом за первое полугодие 2024 года институтом «Красноярскгидропроект» \r\nсделан однозначный вывод об повышении уровня безопасности ГТС до нормального. В отчете \r\nза второе полугодие 2023 было выдано по данному отсеку 10 рекомендаций, причем довольно \r\nтрудозатратных. В отчете за первое полугодие 2024 года было выдано по всем трем отсекам 8 \r\nрекомендаций из разряда «лучшее враг хорошего». ООО» Медвежий ручей» провел \r\nзначительную работу по повышению безопасности ГТС до нормального уровня, свидетельством \r\nтому является утверждение Декларации безопасности ГТС сроком на 5 лет. \r\n5.2.2 Изменение уровня безопасности ГТС никелевого отстойника НОФ \r\nотсек «Южный» за 2023 год.\r\nВ результате сравнения инспекторских отчетов за второе полугодие 2023 года с \r\nинспекторским отчетом за первое полугодие 2024 года институтом «Красноярскгидропроект» \r\nсделан однозначный вывод об повышении уровня безопасности ГТС до нормального. В отчете \r\nза второе полугодие 2023 было выдано по данному отсеку 7 рекомендаций, причем довольно \r\nтрудозатратных. В отчете за первое полугодие 2024 года было выдано по всем трем отсекам 8 \r\nрекомендаций из разряда «лучшее враг хорошего». ООО «Медвежий ручей» провел \r\nзначительную работу по повышению безопасности ГТС до нормального уровня, свидетельством \r\nтому является утверждение Декларации безопасности ГТС сроком на 5 лет. \r\n5.2.3 Изменение уровня безопасности ГТС никелевого отстойника НОФ \r\nотсек «Восточный» за 2023 год.\r\nВ результате сравнения инспекторских отчетов за второе полугодие 2023 года с \r\nинспекторским отчетом за первое полугодие 2024 года институтом «Красноярскгидропроект» \r\nсделан однозначный вывод об повышении уровня безопасности ГТС до нормального. В отчете \r\nза второе полугодие 2023 было выдано по данному отсеку 3 рекомендации., причем довольно \r\nтрудозатратных. В отчете за первое полугодие 2024 года было выдано по всем трем отсекам 8 \r\nрекомендаций из разряда «лучшее враг хорошего». «ООО Медвежий ручей» провел \r\nзначительную работу по повышению безопасности ГТС до нормального уровня, свидетельством \r\nтому является утверждение Декларации безопасности ГТС сроком на 5 лет.", "[стр. 57]\nИнспекторский надзор за отчётный период I полугодия 2024 г гидротехнические сооружения \r\nникелевого отстойника Норильской обогатительной фабрики\r\n56\r\n6 ОСНОВНЫЕ ВЫВОДЫ И РЕКОМЕНДАЦИИ\r\nСпециалистами гидротехниками ООО «Института Красноярскгидропроект» проведено \r\nобследование гидротехнических сооружений никелевого отстойника (отсеки «Северный», \r\n«Южный», «Восточный») Норильской обогатительной фабрики с фотофиксацией дефектов –\r\nоколо 1000 фотографий.\r\nОбследование ГТС Никелевого отстойника НОФ показало, что сооружения находятся в \r\nработоспособном техническом состоянии и соответствуют нормальному уровню безопасности. \r\nПри этом, в ходе обследования было выявлены дефекты и нарушения, которые в \r\nпреимущественном большинстве по категории опасности относятся к категории «В» - дефекты \r\nи повреждения локального характера, которые при последующем развитии не могут влиять на \r\nосновные несущие конструкции, также в меньшем количестве были выявлены дефекты \r\nкатегории «Б», иными словами дефекты и повреждения, игнорирование которых сегодня, в \r\nбудущем с большой долей вероятности спровоцируют повреждения других узлов и элементов –\r\nповреждения и могут перейти в категорию «А».\r\nПо результатам обследования, на сегодняшний день, перед службой эксплуатации, с \r\nцелью сохранения текущего технического состояния и уровня безопасности ГТС Никелевого \r\nотстойника НОФ, стоят следующие задачи: следовать рекомендациям, приведенным по тексту \r\nнастоящего технического отчета, а также решить ряд первоочередных задач:\r\n1) Ликвидировать все понижения гребня ограждающей дамбы;\r\n2) Установить в емкости каждого отсека водомерную рейку с обязательной \r\nфиксацией максимального уровня воды в отсеке и ежегодно переопределять ноль \r\nводомерных реек;\r\n3) Восстановить водопропускную гильзу;\r\n4) Заменить/восстановить железобетонную опору эстакады;\r\n5) Очистить территорию ГТС Никелевого отстойника НОФ от строительно-бытового \r\nмусора;\r\n6) Расчистить русло ручья Медвежий от строительно-бытового мусора и посторонних \r\nпредметов;\r\n7) Провести гидрологические изыскания, определить уровень воды в р. Медвежий \r\nпри 1% обеспеченном расходе в морфологических створах, определить скорости \r\nтечения по створам. Морфологические створы разбить по одному на каждом \r\nотсеке в самом узком месте.\r\n8) В первом триместре 2024 года в среднем были зафиксированы следующие \r\nотметки уровней воды в отсеках никелевого отстойника:\r\n«Южный» - 107,4 м; «Северный» -5,17 м; «Восточный» - 109,38 м.", "[стр. 58]\nТехнический отчёт Часть 1 Инспекторский надзор. Обследование гидротехнических сооружений \r\nхвостохранилища «Лебяжье» Норильской обогатительной фабрики\r\n57\r\nСПИСОК ЛИТЕРАТУРЫ\r\nПри составлении отчёта использованы материалы:\r\n1. Декларация безопасности гидротехнических сооружений никелевого отстойника \r\n(отсеки «Северный, «Южный», «Восточный») Норильской обогатительной \r\nфабрики, ООО «Медвежий ручей» совместно со специалистами ООО «Мигруп \r\nПроект», Норильск, 01.09.2023 г.\r\n2. Правила эксплуатации гидротехнических сооружений никелевого отстойника \r\n(отсеки «Северный», «Южный», «Восточный») Норильской обогатительной \r\nфабрики. Шифр 1006.3-ПЭ. ООО «Институт Красноярскгидропроект», 2023 г.\r\n3. Проект эксплуатации гидротехнических сооружений никелевого отстойника (отсеки \r\n«Северный», «Южный», «Восточный») Норильской обогатительной фабрики на \r\n2024÷2025 гг. Шифр 1006.3-ПрЭ. ООО «Институт Красноярскгидропроект», 2023 г.\r\n4. Проект мониторинга безопасности гидротехнических сооружений никелевого \r\nотстойника (отсеки «Северный», «Южный», «Восточный») Норильской \r\nобогатительной фабрики Шифр 07-04-231. ООО «Мигруп Проект», 2023 г.\r\n5. План ликвидации (локализации) аварий в цехе гидротехнических сооружений и \r\nгидротранспорта Норильской обогатительной фабрики (никелевые отстойники) \r\n2023 г. ООО «Медвежий ручей», 15.12.2022 г.\r\n6. Журналы натурных наблюдений за сооружениями и геотехнического контроля\r\n7. СП 58.13330.2019 Гидротехнические сооружения. Основные положения.\r\n8. СП 39.13330.2012 Плотины из грунтовых материалов. Актуализированная \r\nредакция СНиП 2.06.05-84* (с Изменениями №1, 2, 3).\r\n9. СП 23.13330.2018 Основания гидротехнических сооружений. Актуализированная \r\nредакция СНиП 2.02.02-85 (с Изменением №1).\r\n10. ГОСТ 24846-2019 Грунты. Методы измерения деформаций оснований зданий и \r\nсооружений (с Поправкой).\r\n11. ГОСТ Р 27.002-2015 Надёжность в технике. Надёжность объекта. Термины и \r\nопределения.\r\n12. ГОСТ Р 22.2.09-2015 Безопасность в чрезвычайных ситуациях. Экспертная оценка \r\nуровня безопасности и риска аварий гидротехнических сооружений. Общие \r\nположения.\r\n13. ГОСТ 31937-2011 Здания и сооружения. Правила обследования и мониторинга \r\nтехнического состояния.\r\n14. ГОСТ 27751-2014 Надёжность строительных конструкций и оснований. Основные \r\nположения.\r\n15. СТО 70238424.27.010.011-2008 Здания и сооружения объектов энергетики. \r\nМетодика оценки технического состояния.\r\n16. ГОСТ Р 59873-2021 Гидроэлектростанции. Методика определения критериев \r\nбезопасности для декларируемых гидротехнических сооружений.", "[стр. 59]\nТехнический отчёт Часть 1 Инспекторский надзор. Обследование гидротехнических сооружений \r\nхвостохранилища «Лебяжье» Норильской обогатительной фабрики\r\n58", "[стр. 60]\nПРИЛОЖЕНИЕ А", "[стр. 61]\n", "[стр. 62]\n", "[стр. 63]\n", "[стр. 64]\n", "[стр. 65]\n", "[стр. 66]\n", "[стр. 67]\n", "[стр. 68]\n", "[стр. 69]\n", "[стр. 70]\n", "[стр. 71]\n", "[стр. 72]\n", "[стр. 73]\n", "[стр. 74]\n", "[стр. 75]\n", "[стр. 76]\n", "[стр. 77]\n", "[стр. 78]\nПРИЛОЖЕНИЕ Б", "[стр. 79]\n1006.3-ТО3\r\nИнспекторский надзор за лтчётный период I полугодия 2024 г \r\nгидротехнические сооружений никелевого отстойника Норильской \r\nобогатительной фабрики"]};
